    total = 0
    for fname, blocks in tw.items():
        w = write_page(fname, blocks)
        total += w
        print(f"  {fname.split('_', 1)[1]:60s} {w:5d} words")
    print(f"TOWER 2 DONE — {len(tw)} pages, {total} words")

